tests.oracle:
assert.deepEqual(strokes, [
      { usage: 0x0b, shift: true },
      { usage: 0x0c, shift: false },
      { usage: 0x28, shift: false }
    ]); assert.equal(unsupported, 2);

assert.deepEqual(mapKeyboardEvent("android", { key: "é", code: "KeyE" }, "down"), { kind: "text", text: "é" }); assert.equal(mapKeyboardEvent("android", { key: "é", code: "KeyE" }, "up"), null); assert.deepEqual(mapKeyboardEvent("android", { key: "c", code: "KeyC", ctrlKey: true }, "down"), {
      kind: "android-key",
      action: "down",
      keycode: 31,
      metaState: 0x1000
    }); assert.deepEqual(mapKeyboardEvent("android", { key: "Backspace", code: "Backspace" }, "up"), {
      kind: "android-key",
      action: "up",
      keycode: 67,
      metaState: 0
    });

assert.deepEqual(delays, [500, 1_000, 2_000, 4_000]); assert.deepEqual(
      states.map(([state]) => state),
      ["connecting", "connecting", "error", "error"]
    ); assert.equal(lifecycle.state, "live"); assert.equal(lifecycle.state, "connecting");

assert.ok(frames.length >= 5); assert.ok(packets.every((packet) => packet.version === 1 && packet.serverTimeMs === null)); assert.deepEqual(
      packets.map((packet) => packet.isKey),
      [true, ...Array(frames.length - 1).fill(false)]
    ); assert.ok(pts.every((value, i) => i === 0 || value > pts[i - 1]!), "pts increase");

assert.equal(t.session.sendTouch("begin", 0.5, 0.5), false, "nothing is sent before the socket opens"); assert.equal(t.session.sendText("a".repeat(301)), true); assert.deepEqual(socket.json(), [
      { type: "touch", action: "down", x: 0.25, y: 1, ack: false },
      { type: "touch", action: "move", x: 0.3, y: 0.6, ack: false },
      { type: "touch", action: "up", x: 0, y: 0.6, ack: false },
      { type: "key", keycode: 67 },
      { type: "key", keycode: 31, action: "down", metaState: 0x1000 },
      { type: "recents" },
      { type: "text", text: "a".repeat(300) },
      { type: "text", text: "a" }
    ]);

assert.equal(parseScreenConfig({ width: 0, height: 10, orientation: "portrait" }), null); assert.equal(parseScreenConfig({ width: 10, height: 10, orientation: "sideways" }), null); assert.equal(parseScreenConfig(null), null); assert.deepEqual(parseScreenConfig({ width: 10, height: 20, orientation: "portrait", inputUnavailable: false }), {
      width: 10,
      height: 20,
      orientation: "portrait",
      inputUnavailable: false
    });
